class CoffeeMachine:
    def __init__(self, beans):
        self.beans = beans
        self.cups = 0

    def brew(self, grams=18):
        self.beans -= grams
        self.cups += 1
        return self

m = CoffeeMachine(1000)
for _ in range(3):
    m.brew(grams=18)
